function applyLanguage(lang){
  const dict=T[lang]||T.en;
  document.documentElement.lang=lang;
  document.documentElement.dir=(lang==='ar'||lang==='fa')?'rtl':'ltr';
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const key=el.dataset.i18n;
    if(dict[key]!==undefined) el.innerHTML=dict[key];
    else if(T.en[key]!==undefined) el.innerHTML=T.en[key];
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{
    const key=el.dataset.i18nPlaceholder;
    el.placeholder=dict[key]??T.en[key]??el.placeholder;
  });
  localStorage.setItem('uav-lang',lang);
}
const language=document.getElementById('language');
language.value=localStorage.getItem('uav-lang')||'en';
language.addEventListener('change',e=>applyLanguage(e.target.value));
applyLanguage(language.value);

