function applyCatalogFilter(){
  const filter=document.querySelector('.filter-btn.active')?.dataset.filter||'all';
  const query=(document.getElementById('productSearch')?.value||'').trim().toLowerCase();
  document.querySelectorAll('.product-catalog-grid .product-card').forEach(card=>{
    const haystack=card.textContent.toLowerCase();
    const matchesFilter=filter==='all'||card.dataset.category===filter;
    const matchesSearch=!query||haystack.includes(query);
    card.classList.toggle('is-hidden',!(matchesFilter&&matchesSearch));
  });
}

document.querySelectorAll('.filter-btn').forEach(btn=>btn.addEventListener('click',()=>{
  document.querySelectorAll('.filter-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  applyCatalogFilter();
}));
document.getElementById('productSearch')?.addEventListener('input',applyCatalogFilter);

const imageModal=document.getElementById('imageModal');
const modalImage=document.getElementById('modalImage');
const modalCaption=document.getElementById('modalCaption');
function closeImageModal(){imageModal.classList.remove('open');imageModal.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open');}
document.querySelectorAll('.product-image.zoomable img').forEach(img=>img.addEventListener('click',()=>{
  modalImage.src=img.src; modalImage.alt=img.alt; modalCaption.textContent=img.alt; imageModal.classList.add('open'); imageModal.setAttribute('aria-hidden','false'); document.body.classList.add('modal-open');
}));
document.getElementById('modalClose')?.addEventListener('click',closeImageModal);
imageModal?.addEventListener('click',e=>{if(e.target===imageModal)closeImageModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeImageModal()});

// Close the mobile navigation cleanly and restore desktop layout on resize.
window.addEventListener('resize',()=>{if(innerWidth>900){const nav=document.getElementById('navMenu');nav.classList.remove('open');nav.removeAttribute('style')}});

// Persist cookie dismissal without requiring a backend.
const cookie=document.getElementById('cookie');
if(localStorage.getItem('tch-cookie-ok')==='1') cookie?.remove();
document.getElementById('cookieOk')?.addEventListener('click',()=>{localStorage.setItem('tch-cookie-ok','1');cookie?.remove()});

// Re-apply translations after the TCH UI dictionary is attached.
applyLanguage(language.value);

